    col_bands = _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])

    # A full tile is a nonzero row-band by nonzero column-band; partial edge
    # fragments are ignored. The center cell carries its tile's marker color.
    tiles = []
    for ri, (r0, r1) in enumerate(row_bands):
        rh = r1 - r0 + 1
        if rh < 3:
            continue
        cr = (r0 + r1) // 2
        for ci, (c0, c1) in enumerate(col_bands):
            cw = c1 - c0 + 1
            if cw < 3:
                continue
            cc = (c0 + c1) // 2
            tiles.append((ri, ci, cr, cc, grid[cr][cc]))

    if not tiles:
        return out
    counts = Counter(t[4] for t in tiles)
    background = counts.most_common(1)[0][0]
    active = [t for t in tiles if t[4] != background]

    # Join equal markers in each tile row/column. Only zero cells are drawn on,
    # so the intervening tiles remain intact and the strokes occupy the lanes.
    for axis in (0, 1):
        groups = {}
        for ri, ci, cr, cc, color in active:
            key = (ri, color) if axis == 0 else (ci, color)
            pos = cc if axis == 0 else cr
            groups.setdefault(key, []).append(pos)
        for (_, color), positions in groups.items():
            if len(positions) < 2:
