                matching = [t for t in active if t[0] == _ and t[4] == color] if False else None
                # Positions are ordered along columns; all belong to one tile row.
                rrow = next(t[2] for t in active if t[1] in [ci for ri, ci, *_ in tiles if ri == _] and t[4] == color) if False else None
                # Resolve the center row directly from the row-band index.
                tile_row = next(k[0] for k in groups if k == (_, color))
                r0, r1 = row_bands[tile_row]
