def _span(grid, row, col, color, axis, lo, hi):
    """Contiguous same-color extent around a tile center along one axis."""
    p = row if axis == 0 else col
    start = p
    end = p
    while start > lo:
        rr, cc = (start - 1, col) if axis == 0 else (row, start - 1)
        if grid[rr][cc] != color:
            break
        start -= 1
    while end < hi:
        rr, cc = (end + 1, col) if axis == 0 else (row, end + 1)
        if grid[rr][cc] != color:
            break
        end += 1
    return start, end


def transform(grid):
    output = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_bands = [b for b in _runs([r for r in range(h) if any(grid[r])])
