    col_bands = [b for b in _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])
                 if b[1] - b[0] + 1 >= 3]

    tiles = []
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            r, c = (r0 + r1) // 2, (c0 + c1) // 2
            tiles.append((ri, ci, r, c, grid[r][c]))
    if not tiles:
        return output

    counts = {}
    for t in tiles:
        counts[t[4]] = counts.get(t[4], 0) + 1
    # The common center color is the unmarked/background tile type.
    background = max(counts, key=counts.get)
    markers = [t for t in tiles if t[4] != background]

    # Connect equal marker colors horizontally, preserving their full vertical
    # thickness. Only blank cells are painted, so existing tile content/frame
    # remains unchanged.
    for ri, (r0, r1) in enumerate(row_bands):
        line = (r0 + r1) // 2
        for color in {t[4] for t in markers if t[0] == ri}:
            matching = [t for t in markers if t[0] == ri and t[4] == color]
            if len(matching) < 2:
                continue
            cmin, cmax = min(t[3] for t in matching), max(t[3] for t in matching)
            top, bottom = _span(grid, matching[0][2], matching[0][3], color, 0, r0, r1)
            for r in range(top, bottom + 1):
                for c in range(cmin + 1, cmax):
